'use client';

export default function ServerTimestamp() {
  // Fetch timestamp from server action
  const getServerTime = async () => {
    const response = await fetch('/api/timestamp', {
      cache: 'no-store', // This prevents caching and ensures fresh data
    });
    const data = await response.json();
    return data.timestamp;
  };

  return (
    <div>
      <h2>Server Timestamp</h2>
      <p>Current server time: {new Date().toLocaleString()}</p>
    </div>
  );
}

export default async function ServerTimestamp() {
  // This component is async, which automatically opts out of static prerendering
  // The timestamp will be generated fresh on each request
  const timestamp = new Date().toISOString();

  return (
    <div>
      <h2>Server Timestamp</h2>
      <p>Current server time: {new Date(timestamp).toLocaleString()}</p>
      <p>ISO format: {timestamp}</p>
    </div>
  );
}

